-- edu2impact: create tables and load the current content from data/*.json
-- Import this file into database e2imedu with phpMyAdmin (Import tab). Importing it again replaces everything in these four tables with the content of data/*.json.
SET NAMES utf8mb4;
SET time_zone = '+07:00';

DROP TABLE IF EXISTS post_links;
DROP TABLE IF EXISTS posts;
DROP TABLE IF EXISTS events;
DROP TABLE IF EXISTS site_settings;

CREATE TABLE posts (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  kind        VARCHAR(20)  NOT NULL COMMENT 'research, innovations, workshops, media, news',
  slug        VARCHAR(120) NOT NULL COMMENT 'the old id; used in the URL ?id=',
  title       VARCHAR(400) NOT NULL,
  summary     TEXT NULL,
  body        LONGTEXT NULL COMMENT 'JSON array: paragraphs (text) and image blocks',
  refs        LONGTEXT NULL COMMENT 'JSON array of references, or NULL',
  image       VARCHAR(255) NULL,
  post_date   DATE NULL,
  author      VARCHAR(255) NULL,
  category    VARCHAR(100) NULL,
  tool_url    VARCHAR(500) NULL,
  tool_label  VARCHAR(150) NULL,
  featured    TINYINT(1) NOT NULL DEFAULT 0,
  is_public   TINYINT(1) NOT NULL DEFAULT 1,
  sort_order  INT NOT NULL DEFAULT 0 COMMENT 'order in the old JSON file',
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_kind_slug (kind, slug),
  KEY ix_kind_public (kind, is_public)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE post_links (
  from_kind  VARCHAR(20)  NOT NULL,
  from_slug  VARCHAR(120) NOT NULL,
  to_kind    VARCHAR(20)  NOT NULL,
  to_slug    VARCHAR(120) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (from_kind, from_slug, to_kind, to_slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='the old related field';

CREATE TABLE events (
  id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  title      VARCHAR(400) NOT NULL,
  meta       VARCHAR(400) NULL,
  type       VARCHAR(100) NULL,
  event_date DATE NULL,
  sort_order INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE site_settings (
  setting_key   VARCHAR(50) NOT NULL PRIMARY KEY,
  setting_value TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('research','coding4change-stem-sustainable-innovation','Coding4Change สอนสะเต็มด้วยโค้ดและ AI','โครงการของคณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์ ที่พัฒนาอาจารย์ผู้สอนนักศึกษาครูในเอเชียตะวันออกเฉียงใต้ ให้นำการเขียนโปรแกรมและ AI มาใช้สอนวิชาสะเต็ม เพื่อรับมือกับปัญหาสิ่งแวดล้อม','["Coding4Change เป็นโครงการระดับภูมิภาคที่มีคณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์ เป็นหน่วยงานหลัก กลุ่มเป้าหมายของโครงการคืออาจารย์ผู้สอนนักศึกษาครูในภูมิภาคเอเชียตะวันออกเฉียงใต้ โครงการมุ่งให้อาจารย์กลุ่มนี้นำการเขียนโปรแกรมและ AI เข้าไปใช้ในการสอนวิชาสะเต็ม ซึ่งประกอบด้วยวิทยาศาสตร์ เทคโนโลยี วิศวกรรม และคณิตศาสตร์ รวมทั้งนำงานวิจัยด้านการศึกษามาพัฒนาเป็นกิจกรรมและสื่อการสอนที่ใช้ได้จริง", "อาจารย์ที่เข้าร่วมโครงการจะได้พัฒนาทักษะการเขียนโปรแกรมและการใช้ AI ร่วมกันออกแบบสื่อการสอน และให้ข้อเสนอแนะต่อผลงานของกันและกัน จากนั้นจัดทำแผนการนำไปใช้จริง โดยได้รับการชี้แนะและคำปรึกษาตลอดการดำเนินงาน และมีเครือข่ายอาจารย์ในภูมิภาคสำหรับแลกเปลี่ยนเรียนรู้ร่วมกัน แผนงานของโครงการกำหนดระยะเวลา 12 เดือน และตั้งเป้าหมายไว้ที่อาจารย์ 80 คน และแผนการสอน 80 แผน", "เว็บไซต์โครงการยกตัวอย่างกิจกรรมนำร่องเรื่องการเกษตรที่ปรับตัวต่อสภาพอากาศที่เปลี่ยนไป กิจกรรมนี้ใช้เซนเซอร์ต่อกับคอมพิวเตอร์บอร์ดเล็ก เพื่อวัดความเข้มแสง อุณหภูมิ ความชื้น มุมของแผงโซลาร์ และไฟฟ้าที่แผงผลิตได้ จากนั้นสอน AI ให้ใช้ปัจจัยเหล่านี้ทำนายว่าแผงโซลาร์จะได้พลังงานแสงอาทิตย์ในระดับมาก ปานกลาง หรือน้อย โดย AI เรียนจากข้อมูลจำลองที่ครอบคลุมสภาพอากาศได้กว้างกว่าข้อมูลจริง ส่วนข้อมูลจริงจากเซนเซอร์ใช้ตรวจสอบว่าระบบวัดค่าได้ถูกต้อง ผลพบว่าในบรรดาปัจจัยทั้งหมด ความเข้มแสงเป็นปัจจัยที่ช่วยให้ AI ทำนายระดับพลังงานได้ดีที่สุด ส่วนช่วงเวลาของวัน มุมของแผง อุณหภูมิ และความชื้นช่วยเสริมข้อมูลให้การทำนายดีขึ้น นอกจากนี้ การให้ AI หลายชุดช่วยกันตัดสินยังให้ผลแม่นยำและคงที่กว่าการใช้ชุดเดียว กิจกรรมนี้แสดงให้เห็นว่าการสอนในลักษณะนี้ทำได้จริงทั้งด้านเทคนิคและการสอน แต่ผลต่อการเรียนรู้และประโยชน์ต่อการเกษตรยังต้องศึกษาต่อไป", "รศ. ดร.พงศ์ประพันธ์ พงษ์โสภณ เป็นผู้ประสานงานโครงการ กลุ่ม 77 (G77) อนุมัติทุนจากกองทุน Perez-Guerrero (PGTF) ให้โครงการ โดยมีรัฐบาลไทยสนับสนุน และเครือข่าย AsTEN (Association of Southeast Asian Teacher Education Network) ได้รับรองโครงการแล้ว คณะศึกษาศาสตร์ประกาศเปิดตัวโครงการเมื่อวันที่ 19 ตุลาคม 2569 ข่าวและความคืบหน้าจะประกาศบนเว็บไซต์โครงการ"]','["Coding4Change. (2569). Empowering Teacher Educators in Southeast Asia through Computing-Integrated STEM Education and Machine Learning for Sustainable Innovation. คณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์. https://coding4change.online"]','assets/images/coding4change-pilot.webp','2026-10-22','รศ. ดร.พงศ์ประพันธ์ พงษ์โสภณ และคณะ','Learning','https://coding4change.online/','ไปที่เว็บไซต์โครงการ',0,1,0);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('research','nonthaburi-learning-city-wellbeing-curriculum','หลักสูตรยกระดับนักขับเคลื่อนเมืองแห่งการเรียนรู้ด้านสุขภาวะแบบองค์รวมในสังคมสูงวัยของนครนนทบุรี','หลักสูตร 5 โมดูล ไม่น้อยกว่า 60 ชั่วโมง ที่พัฒนาคนในนครนนทบุรีให้เป็นนักขับเคลื่อนเมืองแห่งการเรียนรู้ ใช้ศิลปะ งานสร้างสรรค์ และภูมิปัญญาท้องถิ่นเชื่อมคนต่างวัย แล้วลงมือจัดกิจกรรมสุขภาวะจริงในชุมชนอย่างน้อย 3 ครั้ง','["นครนนทบุรีมีผู้สูงอายุเพิ่มขึ้นทุกปี ทีมวิจัยจากคณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์ มองเรื่องนี้เป็นโอกาส เพราะผู้สูงอายุมีประสบการณ์และภูมิปัญญาที่ส่งต่อให้คนรุ่นหลังได้ ถ้าเมืองเปิดพื้นที่ให้พวกเขาได้ลงมือทำ ในโครงการวิจัยเรื่องนครนนทบุรีเมืองแห่งการเรียนรู้ของผู้สูงวัย ซึ่งได้ทุนจากกองทุนส่งเสริม ววน. และ บพท. ทีมวิจัยพบว่านนทบุรีมีครบทั้งผู้คน พื้นที่สาธารณะ วัด โรงเรียน ภูมิปัญญา และหน่วยงานที่พร้อมช่วย ที่ติดอยู่คือต่างคนต่างทำ และยังไม่มีใครคอยเชื่อมเข้าหากัน หลักสูตรนี้ตั้งใจสร้าง “นักขับเคลื่อน” มาทำหน้าที่นั้น", {"image": "assets/images/siloed-vs-connected-city.webp", "alt": "ภาพเปรียบเทียบสองฝั่ง ฝั่งซ้ายคือเมืองที่ครอบครัว โรงเรียน และโรงพยาบาลต่างคนต่างอยู่ ฝั่งขวาคือเมืองที่ผู้คนและสถาบันเชื่อมกันเป็นเครือข่าย", "caption": "เมืองที่ทำงานแยกส่วน (ซ้าย) เทียบกับเมืองที่เชื่อมคน พื้นที่ และสถาบันเข้าด้วยกัน (ขวา)"}, "นักขับเคลื่อนชวนคนในชุมชนมาทำกิจกรรมที่ดีต่อชีวิตหลายด้านไปพร้อมกัน ทั้งร่างกาย จิตใจ ความคิด ความสัมพันธ์ และรายได้ เครื่องมือหลักคืองานศิลปะและงานฝีมือจากภูมิปัญญาท้องถิ่น เช่น วาดแมนดาลา ปักผ้า ถักเชือกเมคราเม่ ทำสมุนไพร และทำอาหารพื้นบ้าน งานพวกนี้ดีต่อทั้งกายและใจ และดึงคนต่างวัยมานั่งล้อมวงทำด้วยกันได้ง่าย ผู้สูงอายุสอนฝีมือ ส่วนเด็กและคนวัยทำงานช่วยในเรื่องที่ตัวเองถนัด ใครอยากกลับไปทำอะไรให้ชุมชนก็มาเรียนได้ ทั้งแกนนำชุมชน อาสาสมัคร ผู้สูงอายุ ครู เยาวชน และเจ้าหน้าที่ท้องถิ่น ไม่ต้องเคยทำงานศิลปะมาก่อน แต่ต้องพร้อมลงมือและทำงานกับคนต่างวัยได้", "หลักสูตรใช้เวลาเรียนอย่างน้อย 60 ชั่วโมง แบ่งเป็น 5 โมดูลได้แก่โมดูลแรก (5 ชั่วโมง) ทำความรู้จักแนวคิดเมืองแห่งการเรียนรู้ของ UNESCO และสำรวจว่านนทบุรีมีต้นทุนอะไรและกำลังเจอปัญหาอะไร โมดูลที่สองยาวที่สุด (20 ชั่วโมง) ผู้เรียนเลือกงานฝีมืออย่างน้อยหนึ่งอย่างไปฝึกกับครูภูมิปัญญา และลองใช้ AI ช่วยออกแบบงาน โมดูลที่สาม (15 ชั่วโมง) ออกแบบกิจกรรมที่ผู้สูงอายุและคนต่างวัยเข้าร่วมแล้วสบายใจ จากนั้นลองจัดกับกลุ่มเล็กก่อน โมดูลที่สี่ (10 ชั่วโมง) ฝึกเล่าเรื่อง ใช้สื่อ และชวนวัด โรงเรียน ศูนย์ผู้สูงอายุ เทศบาล และร้านกาแฟในย่านมาร่วม โมดูลสุดท้าย (10 ชั่วโมง) ออกไปจัดกิจกรรมจริงในชุมชน ดูว่าได้ผลแค่ไหน แล้วนั่งวางแผนกับคนในพื้นที่ว่า 60 วันข้างหน้าจะทำอะไรต่อ", "การเรียนเน้นลงมือทำ วิทยากรชวนคิดชวนคุยมากกว่ายืนบรรยาย คนที่จะเรียนจบต้องเข้าเรียนอย่างน้อย 80% ส่งงานครบ จัดกิจกรรมในชุมชนจริงอย่างน้อย 3 ครั้ง และนำผลงานไปเล่าในงานปิดหลักสูตรหรือมหกรรมการเรียนรู้ของเมือง จบแล้วก็ยังมีพี่เลี้ยงคอยดูแลต่อ จากผลที่ทีมวิจัยเก็บได้ คนที่เข้าร่วมมั่นใจในตัวเองมากขึ้น คนต่างวัยในชุมชนสนิทกันขึ้น ทั้งเมืองเริ่มมองการดูแลคนในเมืองเป็นงานที่ต้องทำร่วมกัน และบางคนเอาฝีมือไปต่อยอดจนเป็นอาชีพ ที่เทศกาลนครนนท์ปันสุข ผู้มาร่วมงาน 95% บอกว่าได้เรียนรู้อย่างมาก และ 96% อยากให้จัดอีก", {"image": "assets/images/kalai-mueang-mechanism.webp", "alt": "แผนภาพจากวงสนทนาของคนต่างวัย ความคิดไหลรวมสู่เมืองตรงกลาง แล้วแตกเป็นผลลัพธ์ เช่น ครอบครัว สวนผักชุมชน พื้นที่สีเขียว และการลงมือพัฒนาชุมชน", "caption": "จากวงสนทนาของคนต่างวัยสู่ความคิดร่วมของเมือง และผลลัพธ์ที่เกิดขึ้นในชุมชน"}, "เรื่องทั้งหมดนี้วนกลับมาที่คน นนทบุรีมีผู้สูงอายุ ภูมิปัญญา วัด โรงเรียน และหน่วยงานท้องถิ่นอยู่แล้ว นักขับเคลื่อนคือคนที่ชวนทุกฝ่ายมาทำงานด้วยกัน ผู้สูงอายุได้เป็นคนสอน ส่วนเมืองได้เครือข่ายที่ช่วยกันดูแลคนในเมือง ใครจะนำแนวทางนี้ไปใช้ที่อื่น คู่มือแนะนำให้ “ปรับใช้ ไม่ลอกใช้” คือเก็บแกนคิดไว้ แล้วปรับวิธีให้เข้ากับคนและวัฒนธรรมของแต่ละที่"]','["ชูศักดิ์ เอื้องโชคชัย และคณะ. (2569). หลักสูตรยกระดับนักขับเคลื่อนเมืองแห่งการเรียนรู้ด้านสุขภาวะแบบองค์รวมในสังคมสูงวัยของนครนนทบุรี. คณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์.", "ชูศักดิ์ เอื้องโชคชัย และคณะ. (ม.ป.ป.). คู่มือการสร้างกลไกเมืองแห่งการเรียนรู้เพื่อขับเคลื่อนการเสริมสร้างสุขภาวะองค์รวม. คณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์."]','assets/images/nonthaburi-learning.webp',NULL,'ผศ. ดร.ชูศักดิ์ เอื้องโชคชัย และคณะ','Learning',NULL,NULL,1,1,1);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('research','clil-stem-teacher-assessment-repertory-grid','ครู STEM ที่สอนเป็นภาษาอังกฤษ เลือกวิธีประเมินอย่างไร เมื่อต้องวัดทั้งเนื้อหาและภาษา','งานวิจัยที่ใช้เทคนิคตารางกริด (repertory grid) ชวนครู STEM ในโรงเรียนหลักสูตร English Program 5 คน ตั้งเกณฑ์ประเมินด้วยถ้อยคำของตัวเอง พบว่าครูเลือกงานที่ให้นักเรียนลงมือ ทำงานกลุ่ม และอธิบายความคิด มากกว่าข้อสอบปรนัยหรือแบบเติมคำ','["ในโรงเรียนหลักสูตร English Program ครูคณิตศาสตร์และวิทยาศาสตร์สอนเนื้อหาวิชาเป็นภาษาอังกฤษ แนวทางนี้เรียกว่า CLIL (Content and Language Integrated Learning) คือการเรียนเนื้อหาวิชากับภาษาไปพร้อมกัน เป้าหมายสองด้านทำให้การวัดผลซับซ้อนขึ้น ครูต้องดูทั้งความเข้าใจในเนื้อหาและพัฒนาการทางภาษา โดยไม่ให้ภาษากลายเป็นกำแพงที่บังความรู้ของนักเรียน ที่ผ่านมางานวิจัยเรื่องนี้ในไทยมักดูผลลัพธ์ของหลักสูตรหรือระดับภาษาของนักเรียน ยังไม่ค่อยมีใครถามว่าครูมัธยมเองคิดอย่างไรเวลาเลือกวิธีประเมิน", "ดร.ธนา เครือวงค์ จากคณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์ และรศ. ดร.ปริวรรต อิ่มสอาด จากคณะศิลปศาสตร์ มหาวิทยาลัยธรรมศาสตร์ ศึกษาเรื่องนี้กับครูห้าคนที่สอนคณิตศาสตร์ ชีววิทยา เคมี ฟิสิกส์ และเทคโนโลยีเป็นภาษาอังกฤษมาแล้ว 6 ถึง 10 ปี แทนที่จะแจกแบบสอบถามที่ผู้วิจัยตั้งคำตอบไว้ก่อน ทีมวิจัยใช้เทคนิคตารางกริดจากทฤษฎีโครงสร้างความคิดส่วนบุคคลของ George Kelly ครูแต่ละคนเลือกวิธีประเมินที่ใช้จริงแปดวิธี หยิบมาเทียบกันทีละสามวิธี แล้วบอกด้วยคำของตัวเองว่าสองวิธีไหนคล้ายกันและต่างจากอีกวิธีอย่างไร เช่น สนุกหรือไม่สนุก ใช้ภาษามากหรือน้อย จากนั้นให้คะแนนทุกวิธีตามคู่คำเหล่านั้น และสัมภาษณ์ต่อเป็นภาษาไทยราวครึ่งชั่วโมง", "ภาพที่ได้ต่างกันไปตามวิชา ครูคณิตศาสตร์มองว่างานเติมคำและคำตอบสั้นทำเสร็จเร็วแต่ไม่ค่อยชวนสนุก ส่วนโจทย์แก้ปัญหาและวิจัยขนาดเล็กต้องใช้ทั้งเวลาและภาษามาก ขณะที่เกมกับแผนผังความคิดดึงนักเรียนเข้ามาได้ง่าย ครูชีววิทยาเลือกงานที่ให้นักเรียนอธิบายเหตุผลและลงมือทำ เพราะลดความเครียดและเปิดให้ใช้ภาษาคิดจริง ครูเคมีให้ค่ากับรายงานวิจัย โจทย์แก้ปัญหา และงานในห้องปฏิบัติการ ครูฟิสิกส์ชอบงานกลุ่มที่มีโครงช่วยคิด เช่น การอภิปราย แผนผังมโนทัศน์ รายงานการทดลอง และเกม ส่วนครูเทคโนโลยีเลือกการนำเสนอปากเปล่ากับโครงงานขนาดเล็ก", {"image": "assets/images/clil-chemistry-focus-grid.webp", "alt": "ผลวิเคราะห์ FOCUS จากตารางกริดของครูเคมี ด้านซ้ายเป็นคู่คำ เช่น นักเรียนมีส่วนร่วมมากกับน้อย ใช้ภาษามากกับน้อย ตรงกลางเป็นตารางคะแนน 1 ถึง 5 ด้านขวาและด้านล่างเป็นแผนภูมิต้นไม้ที่จัดกลุ่มคู่คำและวิธีประเมินที่ได้คะแนนคล้ายกัน ได้แก่ คำตอบสั้น นำเสนอ เขียนสรุป แก้ปัญหา วิเคราะห์เอกสาร สอบปากเปล่า รายงานวิจัย และทักษะในห้องปฏิบัติการ", "caption": "ผลวิเคราะห์ตารางกริดของครูเคมี แผนภูมิด้านขวาและด้านล่างจัดกลุ่มคู่คำและวิธีประเมินที่ครูให้คะแนนคล้ายกัน (ภาพจาก Kruawong & Imsa-ard, 2024)"}, "เมื่อมองรวมกัน ครูทั้งห้าคนเอนไปทางเดียวกัน คืองานที่ให้นักเรียนลงมือ คุยกัน และทำงานเป็นกลุ่ม เพราะงานแบบนี้ทำให้นักเรียนต้องใช้ภาษาอังกฤษเพื่อคิดและอธิบายจริง ไม่ใช่แค่จำศัพท์ ส่วนข้อสอบปรนัยและแบบฝึกออนไลน์ยังวัดความรู้เฉพาะจุดได้ดี แต่ไม่ค่อยชวนให้นักเรียนพูดหรือเขียน เว้นแต่ออกแบบให้มีการทำงานร่วมกัน ผู้วิจัยยังสังเกตว่าครูฟิสิกส์ไทยใช้เกมมากกว่าห้องเรียน CLIL บางแห่งในตะวันตก และครูคณิตศาสตร์ก็ใช้เกมกับแผนผังความคิดควบคู่กับการฝึกอธิบายด้วยภาษา ซึ่งสะท้อนการปรับวิธีให้เข้ากับนักเรียนในบริบทของตัวเอง", "ผู้วิจัยชี้ว่าเกณฑ์ที่ครูแต่ละคนใช้เป็นของเฉพาะตัว ได้ผลในห้องของตัวเอง แต่ทำให้การวางมาตรฐานร่วมกันระหว่างห้องเรียนทำได้ยาก การพัฒนาครูเรื่องการประเมินใน CLIL จึงควรแยกตามพื้นฐานของครู ครูวิทยาศาสตร์และคณิตศาสตร์ต้องการแนวทางสอดแทรกเป้าหมายด้านภาษา ส่วนครูภาษาอังกฤษต้องการแนวทางนำเนื้อหาวิชาเข้ามา และควรมองการประเมินเป็นส่วนหนึ่งของการเรียน ไม่ใช่ด่านสุดท้าย งานนี้ศึกษาครูเพียงห้าคนจากข้อมูลที่ครูเล่าเอง โดยไม่ได้สังเกตในห้องเรียน จึงไม่ใช่ข้อสรุปของครูทั้งประเทศ แต่ตารางกริดเองก็เป็นเครื่องมือที่โรงเรียนนำไปใช้ให้ครูได้ทบทวนวิธีคิดของตัวเองได้"]','["Kruawong, T., & Imsa-ard, P. (2024). Investigating STEM secondary school teachers\' CLIL assessment practices in EFL contexts: The repertory grid technique. RELC Journal, 1–21. https://doi.org/10.1177/00336882241304123"]','assets/images/clil-hand.webp','2024-12-16','ดร.ธนา เครือวงค์ และ รศ. ดร.ปริวรรต อิ่มสอาด','Assessment',NULL,NULL,0,0,2);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('innovations','ku-care-u','KU care U เช็กก่อน เชื่อทีหลัง','เว็บไซต์ที่ให้นิสิตและบุคลากรมหาวิทยาลัยเกษตรศาสตร์ตรวจสอบเลขบัญชี เบอร์โทรศัพท์ ชื่อ ข้อความ และลิงก์เว็บไซต์เบื้องต้นก่อนโอนเงิน และแจ้งเหตุได้เมื่อเจอกลโกงออนไลน์','["มิจฉาชีพออนไลน์มักเร่งให้โอนเงินทันที หรือหลอกให้กดลิงก์และบอกรหัส OTP ก่อนที่เหยื่อจะมีเวลาคิด KU care U จึงตั้งหลักไว้สั้น ๆ ว่า \\"เช็กก่อน เชื่อทีหลัง\\" เว็บไซต์นี้เปิดให้นิสิตและบุคลากรมหาวิทยาลัยเกษตรศาสตร์ตรวจสอบข้อมูลเบื้องต้นก่อนโอนเงินหรือกดลิงก์ โดยเข้าใช้งานด้วยบัญชี Google ซึ่งใช้ยืนยันตัวตนเท่านั้น ระบบไม่ได้เข้าถึงรหัสผ่าน", "เครื่องมือมีห้าแบบ สำหรับเลขบัญชีธนาคาร พร้อมเพย์ และวอลเล็ต เบอร์โทรศัพท์ และชื่อ-นามสกุล ระบบจะค้นจากรายงานที่ผู้ดูแลตรวจและอนุมัติแล้ว สำหรับข้อความที่น่าสงสัย ผู้ใช้วางข้อความหรือแนบภาพหน้าจอได้สูงสุด 3 ภาพ ระบบจะอ่านข้อความในภาพแล้วชี้จุดที่น่าเป็นห่วงให้ ส่วนลิงก์เว็บไซต์ ระบบดูจากลักษณะของ URL โดยไม่เปิดลิงก์นั้น ถ้าเจอกลโกง ผู้ใช้แจ้งเหตุพร้อมหลักฐานได้ รายงานใหม่จะรอผู้ดูแลตรวจหลักฐานก่อนอนุมัติ เพื่อไม่ให้คนที่ไม่เกี่ยวข้องถูกกล่าวหา และแบบฟอร์มเตือนไม่ให้กรอกรหัส OTP รหัสผ่าน หรือเลขบัตรประชาชน", "KU care U บอกข้อจำกัดของตัวเองไว้ตรง ๆ ผลตรวจเป็นข้อมูลเบื้องต้น ระบบไม่ได้เชื่อมกับธนาคารหรือตำรวจ และการวิเคราะห์อัตโนมัติอาจผิดพลาดได้ ถ้าผลขึ้นว่ายังไม่พบประวัติการรายงาน แปลว่ายังไม่มีใครแจ้งเข้ามาในระบบ ไม่ได้แปลว่าบัญชีนั้นปลอดภัย ถ้าสงสัย ให้หยุดโอนแล้วตรวจสอบอีกครั้ง และถ้าโอนเงินไปแล้ว เว็บไซต์แนะนำให้โทรหาธนาคารทันทีเพื่อขอระงับบัญชีปลายทาง เก็บสลิปและแชตไว้เป็นหลักฐาน แล้วแจ้งความออนไลน์ที่ thaipoliceonline.go.th หรือโทรสายด่วน 1441"]',NULL,'assets/images/innovation-ku-care-u.webp','2026-10-22',NULL,'Technology','https://ku-care-u.netlify.app/','เปิดใช้ KU care U',0,1,0);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('innovations','smart-garden-stem-robotics-coding','Smart Garden with STEM Robotics and Coding หลักสูตรชวนเด็กประถมเรียนรู้การทำสวนแบบดิจิทัล','ต้นแบบหลักสูตรสะเต็มศึกษาสำหรับนักเรียนประถมศึกษาตอนปลาย ที่ใช้แปลงผักของโรงเรียนเป็นโจทย์ให้นักเรียนเขียนโปรแกรม สร้างหุ่นยนต์ และใช้ปัญญาประดิษฐ์ ไปพร้อมกับคิดว่าเทคโนโลยีที่ตัวเองสร้างส่งผลต่อผู้คนและชุมชนอย่างไร','["งานวิจัยด้านสะเต็มศึกษาในไทยพบว่า โรงเรียนหลายแห่งยังขาดอุปกรณ์ และการเรียนวิทยาศาสตร์กับเทคโนโลยียังเชื่อมกับสถานการณ์จริงไม่มากนัก นักเรียนจำนวนมากจึงไม่ค่อยได้จับหุ่นยนต์หรือเขียนโปรแกรม ขณะที่การเกษตรเริ่มใช้เซนเซอร์และระบบอัตโนมัติมากขึ้นทุกที UNESCO เสนอว่าพลเมืองโลกในยุคดิจิทัลต้องเข้าใจผลกระทบของเทคโนโลยีต่อชุมชน วิเคราะห์ข้อมูลได้ รับผิดชอบต่อสังคม ใช้เทคโนโลยีแก้ปัญหาจริง และมีส่วนร่วมกับชุมชน เด็กที่สร้างหุ่นยนต์เป็นจึงควรถามต่อได้ว่า หุ่นยนต์ตัวนั้นช่วยใคร กระทบใคร และถ้ามันทำงานผิด ใครต้องรับผิดชอบ", "ทีมวิจัยนำโดย รศ. ดร. ศศิเทพ ปิติพรเทพิน คณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์ ร่วมกับนักวิจัยจากจุฬาลงกรณ์มหาวิทยาลัย มหาวิทยาลัยเชียงใหม่ และมหาวิทยาลัยมหิดล มี Professor Dr. Samia Khan จาก The University of British Columbia เป็นที่ปรึกษา และได้รับทุนสนับสนุนงานมูลฐาน (Fundamental Fund) ปีงบประมาณ 2569 หลักสูตรใช้สวนอัจฉริยะเป็นโจทย์ ปัญหาอย่างดินแห้ง แสงไม่พอ หรือแมลงลงแปลง เป็นสิ่งที่นักเรียนเห็นได้เองในแปลงผักของโรงเรียน งานวิจัยนี้จึงมีเป้าหมายสองข้อ คือพัฒนาต้นแบบหลักสูตรสะเต็มศึกษาที่เตรียมนักเรียนประถมศึกษาตอนปลายให้พร้อมเป็นพลเมืองในยุคดิจิทัล และศึกษาว่าหลังเรียน ความเป็นพลเมืองโลกในยุคดิจิทัลของนักเรียนเปลี่ยนไปอย่างไร รวมถึงนักเรียนพอใจกับหลักสูตรแค่ไหน", "การวิจัยมีสองระยะ ระยะแรก ทีมวิจัยสัมภาษณ์ครูประถมปลายถึงการสอนเทคโนโลยีและสิ่งที่ครูต้องการ แล้วร่างหลักสูตร 20 ชั่วโมงให้ผู้เชี่ยวชาญตรวจ ผู้เชี่ยวชาญประเมินว่าเหมาะสมในระดับมากที่สุด และชี้ว่าหลักสูตรทำให้หุ่นยนต์กับปัญญาประดิษฐ์เป็นเรื่องที่จับต้องได้ผ่านการลงมือทำทีละขั้น เนื้อหาไล่ความยากเป็นสามระดับ ระดับพื้นฐานเริ่มจากเขียนโปรแกรมบอร์ด Micro:bit ให้อ่านค่าความชื้นในดินและแสง แล้วแจ้งเตือนเมื่อค่าต่ำเกินไป ระดับกลาง นักเรียนสร้างเครื่องรดน้ำอัตโนมัติและรถหุ่นยนต์ติดแขนจับช่วยเก็บผลผลิต ระดับสูง นักเรียนฝึกกล้องปัญญาประดิษฐ์ให้จำภาพ เพื่อใช้ตรวจโรคพืชและไล่แมลง ปิดท้ายด้วยโครงงานที่นักเรียนออกแบบเองเพื่อแก้ปัญหาการเกษตรของโรงเรียนหรือชุมชน ระหว่างลงมือทำ ทีมวิจัยแนะนำให้ครูชวนคิด เช่น ถ้าเครื่องรดน้ำรดจนน้ำท่วมแปลง ใครต้องรับผิดชอบ คนเขียนโค้ด เซนเซอร์ หรือ AI และเมื่อหุ่นยนต์ไม่ทำงาน ครูยังไม่ต้องเข้าไปแก้ให้ แต่ถามให้นักเรียนไล่ตรวจโค้ดและสายไฟเอง", {"image": "assets/images/smart-garden-auto-watering.webp", "alt": "ชุดรดน้ำต้นไม้อัตโนมัติบนโต๊ะ บอร์ด Micro:bit บนแผงขยายพร้อมจอ OLED ต่อสายไปยังหัววัดในแก้วพลาสติกและโมดูลรีเลย์สีน้ำเงิน มีสายยางใสจากโถแก้วใส่น้ำไปยังกระถางต้นไม้", "caption": "เครื่องรดน้ำอัตโนมัติ ใช้ค่าความชื้นในดินเป็นตัวสั่งให้ปั๊มน้ำทำงาน"}, "ระยะที่สอง ทีมวิจัยทดลองหลักสูตรกับนักเรียนกลุ่มเล็ก ปรับแก้ แล้วใช้จริงกับนักเรียนประถมปลาย โดยวัดความเป็นพลเมืองโลกในยุคดิจิทัลก่อนและหลังเรียน และสอบถามความพึงพอใจ หลังเรียน ความเป็นพลเมืองโลกในยุคดิจิทัลของนักเรียนดีขึ้นทั้งห้าด้าน นักเรียนพอใจหลักสูตรในระดับมากที่สุด และชอบที่สุดตรงที่ได้จับอุปกรณ์จริง ในการสัมภาษณ์หลังเรียน นักเรียนมองเทคโนโลยีทั้งสองด้าน คนหนึ่งเห็นว่าหุ่นยนต์ช่วยให้เกษตรกรสูงวัยทำงานได้นานขึ้น อีกคนกังวลว่า \\"ถ้าสมมติให้หุ่นยนต์เข้าไปทำงานก็อาจจะทำให้เกษตรกรตกงานไม่มีงานทำ\\" และมีคนหนึ่งขอให้จัดกิจกรรมนี้อีก \\"เพื่อให้น้อง ๆ ของพวกผมเนี่ยครับ ได้เรียนสิ่งที่ผมได้เรียนด้วยครับ\\"", {"image": "assets/images/smart-garden-gripper-robot.webp", "alt": "รถหุ่นยนต์ฐานกลมสีเหลืองติดแขนจับสีดำและบอร์ดควบคุม จอดอยู่บนดินในแปลงผักเคล", "caption": "รถหุ่นยนต์ติดแขนจับสำหรับช่วยเก็บผลผลิต"}, "ผลการวิจัยชี้ว่า เมื่อนักเรียนใช้เทคโนโลยีกับปัญหาที่เห็นได้จริงในแปลงผัก ทักษะการเขียนโปรแกรมกับการคิดถึงผลกระทบต่อคนและชุมชนฝึกไปพร้อมกันได้ หลักสูตรนี้ยังเป็นต้นแบบ ผู้เชี่ยวชาญเสนอให้นักเรียนวัดค่าในแปลงจริงแล้วกำหนดเกณฑ์การทำงานเอง และพิจารณาต้นทุนอุปกรณ์ที่ยังค่อนข้างสูง นักเรียนเองก็ขอเวลามากขึ้น เพื่อจะได้ลองผิดลองถูกจนชิ้นงานทำงานได้ตามที่ตั้งใจ"]','["ศศิเทพ ปิติพรเทพิน, สุกานดา จงเสริมตระกูล, ชาตรี ฝ่ายคำตา, ศรินย์พร ชัยวิศิษฎ์, สุขรัชต์ดา วงศ์บุญเอื้อ และมนต์อมร ปรีชารัตน์. (2569). การพัฒนาต้นแบบหลักสูตรการเรียนรู้สะเต็มศึกษา \\"Smart Garden with STEM Robotics and Coding\\" เพื่อเตรียมพร้อมผู้เรียนสู่การเป็นพลเมืองโลกในยุคดิจิทัล [รายงานวิจัยฉบับสมบูรณ์]. คณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์."]','assets/images/smart-garden-cover.webp','2026-10-21','รศ. ดร. ศศิเทพ ปิติพรเทพิน และคณะ','Learning',NULL,NULL,0,1,1);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('innovations','pck-canvas','PCK Canvas แบบหนึ่งแผ่นออกแบบหลักสูตรอย่างเป็นระบบ','Canvas หนึ่งแผ่นที่ช่วยให้ครูทุกกลุ่มสาระการเรียนรู้สามารถออกแบบและพัฒนาบทเรียนได้อย่างเป็นระบบ ตั้งแต่การกำหนดแก่นความรู้และแนวคิดสำคัญของเนื้อหา การวิเคราะห์ความรู้เดิมและความเข้าใจคลาดเคลื่อนของผู้เรียน การเลือกวิธีจัดการเรียนรู้และกิจกรรมที่เหมาะสม การออกแบบคำถามและการใช้สื่อหรือนวัตกรรมเพื่อส่งเสริมการเรียนรู้ ไปจนถึงการกำหนดหลักฐานการคิดและการเรียนรู้ของผู้เรียน ตลอดจนการประเมินผลและการให้ข้อมูลย้อนกลับ โดยปรับแนวทางการใช้ Canvas และระดับการสนับสนุนให้สอดคล้องกับบริบท ประสบการณ์ ความเชี่ยวชาญ และความต้องการในการพัฒนาของครูแต่ละคน เพื่อเชื่อมโยงความรู้ในเนื้อหาวิชาเข้ากับศาสตร์การสอนและการเรียนรู้ของผู้เรียนอย่างมีประสิทธิภาพ','[]','["ชาตรี ฝ่ายคำตา และคณะ. (2566). PCK Canvas เพื่อพัฒนาสมรรถนะการเรียนรู้วิทยาศาสตร์.", "Gess-Newsome, J. (1999). Pedagogical content knowledge: An introduction and orientation. In J. Gess-Newsome & N. G. Lederman (Eds.), Examining pedagogical content knowledge (pp. 3–17). Kluwer.", "van de Pol, J., Volman, M., & Beishuizen, J. (2010). Scaffolding in teacher–student interaction: A decade of research. Educational Psychology Review, 22(3), 271–296."]','assets/images/innovation-pck-canvas.webp','2026-10-15','รศ. ดร. ชาตรี ฝ่ายคำตา และคณะ','Improvement','apps/pck-canvas/','เปิดใช้ PCK Canvas',1,1,2);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('innovations','hemo-link','Hemo-Link แบบจำลองที่ทำให้การรวมกลุ่มของเม็ดเลือดแดงมองเห็นได้','ชุดปฏิบัติการจำลองการตรวจหมู่เลือดและแบบจำลองแอนติเจน–แอนติบอดี สำหรับชีววิทยา ม.5 ที่ให้นักเรียนสร้าง ทดสอบ และปรับแบบจำลองจากหลักฐาน จนอธิบายได้ว่าหมู่เลือด A, B, AB และ O ต่างกันอย่างไรในเลือดจริง','["หลายคนรู้ว่าตัวเองเลือดหมู่อะไร แต่น้อยคนจะบอกได้ว่าตัวอักษร A, B, AB หรือ O หมายถึงอะไรในเลือดจริง เรื่องหมู่เลือดระบบ ABO ในวิชาชีววิทยามีคำศัพท์เฉพาะมาก และเป็นเรื่องที่ตามองไม่เห็น ส่วนการตรวจหมู่เลือดจริงในห้องเรียนก็ทำได้ยาก เพราะน้ำยามีราคาสูงและหาซื้อยาก ต้องคำนึงถึงความปลอดภัยและจริยธรรมของการทดลองกับเลือดคน งานวิจัยที่ผ่านมายังพบความเข้าใจคลาดเคลื่อนที่พบบ่อย เช่น คิดว่า A และ B เป็นแค่ชื่อเรียก คิดว่าแอนติเจนกับแอนติบอดีอยู่บนผิวเซลล์เม็ดเลือดแดงเหมือนกัน หรือคิดว่าหมู่ O มีแอนติเจนทั้ง A และ B", "Hemo-Link (Blood Agglutination Visualizing Model) เป็นนวัตกรรมที่ นภสินธุ์ ภัครัตน์ นิสิตปริญญาโท สาขาวิชาวิทยาศาสตร์ศึกษา คณะศึกษาศาสตร์ มหาวิทยาลัยเกษตรศาสตร์ พัฒนาขึ้นในรายวิชานวัตกรรมการศึกษาวิทยาศาสตร์เพื่อการพัฒนาที่ยั่งยืน โดยมี รศ. ดร.ชาตรี ฝ่ายคำตา และ รศ. ดร.จีระวรรณ เกษสิงห์ เป็นอาจารย์ที่ปรึกษา นวัตกรรมมีสองส่วนทำงานคู่กัน ส่วนแรกคือห้องปฏิบัติการจำลอง ใช้น้ำนมผสมสีแทนตัวอย่างเลือด และใช้น้ำยาจำลอง Anti-A, Anti-B และ Anti-D ที่ทำให้ตัวอย่างจับตัวเป็นก้อนหรือไม่จับตัว นักเรียนจึงเห็นผลการรวมกลุ่มได้จริงโดยไม่ต้องใช้เลือดคน ส่วนที่สองคือแบบจำลองที่ใช้ฟองน้ำสีแดงแทนเซลล์เม็ดเลือดแดง หมุดติดบอร์ดแทนแอนติเจน และคลิปหนีบกระดาษแทนแอนติบอดี โดยใช้สีให้ตรงกับน้ำยาแต่ละชนิด", {"image": "assets/images/hemo-link-prototype.webp", "alt": "ต้นแบบชุดอุปกรณ์ Hemo-Link ฝั่งซ้ายเป็นขวดน้ำยาจำลองและซองชุดตรวจหมู่เลือด ฝั่งขวาเป็นลูกฟองน้ำสีแดง หมุดสีเหลือง น้ำเงิน ขาว และคลิปหนีบกระดาษหลายสี แยกใส่ถุง", "caption": "ต้นแบบชุดปฏิบัติการจำลองการตรวจหมู่เลือด (ซ้าย) และชุดแบบจำลองแอนติเจน–แอนติบอดี (ขวา)"}, "บทเรียนออกแบบตามแนวการสืบเสาะโดยใช้แบบจำลองเป็นฐาน (Model-Based Inquiry) ของ Windschitl และคณะ (2008) เริ่มจากสถานการณ์ผู้บาดเจ็บจากอุบัติเหตุที่เสียเลือดมาก ต้องได้รับเลือดด่วน แต่ไม่มีเอกสารระบุหมู่เลือด นักเรียนตรวจตัวอย่างเลือดจำลองเทียบกับชุดตรวจหมู่เลือดแต่ละแบบ แล้วตั้งคำถามต่อว่าทำไมเลือดตัวอย่างนี้จึงรวมกลุ่มเมื่อเจอ Anti-B แต่ไม่รวมกลุ่มเมื่อเจอ Anti-A", {"image": "assets/images/hemo-link-mechanism.webp", "alt": "แผนภาพองค์ประกอบห้าส่วนของ Hemo-Link ได้แก่ การจำลองปฏิบัติการตรวจหมู่เลือด แบบจำลอง ใบกิจกรรมรวบรวมหลักฐาน การสืบเสาะโดยใช้แบบจำลองเป็นฐาน และเทคนิคนั่งร้านเสริมเรียนรู้ รวมกันเป็นนวัตกรรม Hemo-Link", "caption": "องค์ประกอบห้าส่วนที่ประกอบกันเป็น Hemo-Link"}, "นักเรียนทำงานเป็นกลุ่มละ 4–5 คน สร้างแบบจำลองเบื้องต้นที่ต้องแสดงสามเรื่องได้แก่ สิ่งที่อยู่บนเซลล์เม็ดเลือดแดง สิ่งที่อยู่ในน้ำยาทดสอบ และการเปลี่ยนแปลงที่ทำให้เซลล์รวมกลุ่มกัน จากนั้นหาหลักฐานเพิ่มจากคลิปวิดีโอและแหล่งข้อมูล บันทึกลงใบกิจกรรม แล้วนำกลับมาปรับแบบจำลองของกลุ่ม เมื่อเจอสถานการณ์ใหม่ที่ซับซ้อนขึ้น ทั้งชั้นเรียนสร้างแบบจำลองร่วมกัน เขียนคำอธิบายทางวิทยาศาสตร์ และประเมินงานของเพื่อนแบบไม่ระบุชื่อ ก่อนสรุปร่วมกับครู", "ในรุ่นพัฒนา แบบจำลองเพิ่มแอนติเจนและแอนติบอดี D สำหรับหมู่เลือด Rh ทำปลายของแอนติเจนและแอนติบอดีแต่ละชนิดให้มีขนาดเฉพาะ เพื่อให้เห็นว่ามีเพียงคู่ที่ตรงกันเท่านั้นที่จับกันได้ และเพิ่มแผ่นแสดงพื้นที่ของน้ำเลือด เพื่อให้เห็นว่าเซลล์เม็ดเลือดแดง แอนติเจน และแอนติบอดีล้วนอยู่ภายในเลือด", {"image": "assets/images/hemo-link-model-kit.webp", "alt": "ภาพชุดแบบจำลองการตรวจหมู่เลือดในกล่องพลาสติก มีลูกบอลสีแดงแทนเซลล์เม็ดเลือดแดง ชิ้นแอนติเจนและแอนติบอดีสีฟ้า เหลือง และขาว พร้อมวิธีประกอบสี่ขั้นและตัวอย่างคู่ที่จับกันได้และจับกันไม่ได้", "caption": "แนวคิดชุดแบบจำลองรุ่นพัฒนา แอนติเจนและแอนติบอดีแต่ละชนิดจับกันได้เฉพาะคู่ที่ตรงกัน"}, "ผู้พัฒนามองคุณค่าของ Hemo-Link ไว้สามระดับได้แก่ 1) นักเรียนได้เห็นการเกิดและไม่เกิดการรวมกลุ่มของเม็ดเลือดแดงเป็นรูปธรรม 2) เข้าใจกระบวนการที่เกิดขึ้นในระดับโมเลกุล และ 3) ได้สัมผัสธรรมชาติของความรู้วิทยาศาสตร์ที่ทดสอบได้และปรับแก้ได้ ครูได้ทำหน้าที่ผู้ออกแบบสถานการณ์และใช้หลักฐานจากงานของนักเรียนพัฒนาการสอน ส่วนโรงเรียนได้แนวทางจัดปฏิบัติการชีววิทยาที่ใช้สารเคมีน้อยลง ลดของเสียจากการทดลอง และปลอดภัยกว่าเดิม"]',NULL,'assets/images/hemo-link-cover.webp','2026-10-20','นภสินธุ์ ภัครัตน์','Learning',NULL,NULL,0,1,3);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('workshops','hemo-link-blood-type-model-workshop','เวิร์กช็อป Hemo-Link: สอนหมู่เลือด ABO ด้วยแบบจำลองที่จับต้องได้','ครูได้ลองตรวจหมู่เลือดจำลองและต่อแบบจำลองแอนติเจน–แอนติบอดีด้วยมือ แล้วนำไปสอนหมู่เลือด ABO แบบที่นักเรียนเห็นและอธิบายได้เอง','["หมู่เลือด ABO เป็นเรื่องที่ตามองไม่เห็น และการตรวจเลือดจริงในห้องเรียนก็ทำได้ยาก ทั้งเรื่องราคาน้ำยา ความปลอดภัย และจริยธรรม เวิร์กช็อปนี้เริ่มจากสถานการณ์ผู้บาดเจ็บที่เสียเลือดมากและต้องได้รับเลือดด่วน ครูจะได้สวมบทนักเรียน ตรวจตัวอย่างเลือดจำลองด้วยน้ำยาจำลอง Anti-A, Anti-B และ Anti-D ซึ่งจับตัวเป็นก้อนให้เห็นจริงโดยไม่ต้องใช้เลือดคน จากนั้นแบ่งกลุ่มต่อแบบจำลองที่ใช้ฟองน้ำแทนเซลล์เม็ดเลือดแดง หมุดแทนแอนติเจน และคลิปหนีบกระดาษแทนแอนติบอดี ทดสอบแบบจำลองกับผลที่ตรวจได้ แล้วปรับจนอธิบายได้ว่าทำไมเลือดแต่ละหมู่ถึงจับตัวต่างกัน", "เมื่อจบเวิร์กช็อป ครูจะได้ลำดับกิจกรรมที่นำไปสอนชีววิทยา ม.5 ได้ทันที และรู้ว่านักเรียนมักเข้าใจคลาดเคลื่อนตรงไหน เช่น คิดว่า A และ B เป็นแค่ชื่อเรียก หรือคิดว่าหมู่ O มีแอนติเจนทั้ง A และ B พร้อมวิธีใช้แบบจำลองให้นักเรียนเห็นและแก้ความเข้าใจนั้นเอง ครูยังได้แนวทางจัดปฏิบัติการชีววิทยาที่ใช้สารเคมีน้อยลงและปลอดภัยกว่าเดิม ด้วยวัสดุที่หาได้ทั่วไป ส่วนนักเรียนจะได้อธิบายหมู่เลือดจากหลักฐานที่ตัวเองตรวจและทดสอบมาเอง"]',NULL,'assets/images/hemo-link-cover.webp',NULL,'นภสินธุ์ ภัครัตน์',NULL,NULL,NULL,0,1,0);
INSERT INTO post_links (from_kind,from_slug,to_kind,to_slug,sort_order) VALUES ('workshops','hemo-link-blood-type-model-workshop','innovations','hemo-link',0);
INSERT INTO posts (kind,slug,title,summary,body,refs,image,post_date,author,category,tool_url,tool_label,featured,is_public,sort_order) VALUES ('workshops','nonthaburi-learning-city-facilitator-workshop','เวิร์กช็อปนักขับเคลื่อนเมืองแห่งการเรียนรู้: เชื่อมคนต่างวัยด้วยศิลปะและภูมิปัญญาท้องถิ่น','ใช้ศิลปะ งานฝีมือ และภูมิปัญญาท้องถิ่น ออกแบบกิจกรรมที่ชวนผู้สูงอายุ เด็ก และคนวัยทำงานในชุมชนมาเรียนรู้และดูแลกันและกัน','["หลายชุมชนมีผู้สูงอายุ ภูมิปัญญา วัด โรงเรียน และหน่วยงานที่พร้อมช่วยอยู่แล้ว แต่ต่างคนต่างทำ เวิร์กช็อปนี้ฝึกคนที่จะชวนทุกฝ่ายมาทำงานด้วยกัน ผู้เข้าร่วมจะได้ลองงานฝีมือที่ทำร่วมกันได้ง่าย เช่น วาดแมนดาลา ปักผ้า ทำสมุนไพร หรือทำอาหารพื้นบ้าน แล้วใช้เป็นจุดเริ่มของวงพูดคุยระหว่างคนต่างวัย ช่วงหลังเป็นการออกแบบกิจกรรมสุขภาวะสำหรับพื้นที่ของตัวเอง ที่ผู้สูงอายุเข้าร่วมแล้วสบายใจ และวางแผนว่าจะชวนวัด โรงเรียน ศูนย์ผู้สูงอายุ หรือเทศบาลมาร่วมอย่างไร ไม่ต้องเคยทำงานศิลปะมาก่อน แค่พร้อมลงมือและทำงานกับคนต่างวัยได้", "ผู้เข้าร่วมจะกลับไปพร้อมแผนกิจกรรมสุขภาวะที่จัดในชุมชนของตัวเองได้จริง และรู้วิธีใช้งานฝีมือดึงคนต่างวัยมานั่งทำด้วยกัน ให้ผู้สูงอายุได้เป็นคนสอน ส่วนเด็กและคนวัยทำงานช่วยในเรื่องที่ตัวเองถนัด รวมถึงได้แนวทางชวนหน่วยงานในพื้นที่มาเป็นเครือข่าย ชุมชนที่ใช้แนวทางนี้มาแล้วพบว่าคนต่างวัยสนิทกันขึ้น ผู้เข้าร่วมมั่นใจในตัวเองมากขึ้น และบางคนนำฝีมือไปต่อยอดเป็นอาชีพ หลักที่ใช้ตลอดเวิร์กช็อปคือ \\"ปรับใช้ ไม่ลอกใช้\\" เก็บแกนคิดไว้ แล้วปรับวิธีให้เข้ากับคนและวัฒนธรรมของแต่ละที่"]',NULL,'assets/images/nonthaburi-learning.webp',NULL,'ผศ. ดร.ชูศักดิ์ เอื้องโชคชัย และคณะ',NULL,NULL,NULL,0,1,1);
